package com.example.spendwiseai.data.repository

import com.google.firebase.auth.FirebaseAuth
import com.google.firebase.auth.FirebaseUser
import com.google.firebase.auth.GoogleAuthProvider
import kotlinx.coroutines.channels.awaitClose
import kotlinx.coroutines.flow.Flow
import kotlinx.coroutines.flow.callbackFlow
import kotlinx.coroutines.tasks.await

class AuthRepository {
    private val auth = FirebaseAuth.getInstance()

    val currentUser: FirebaseUser? get() = auth.currentUser

    val authStateFlow: Flow<FirebaseUser?> = callbackFlow {
        val listener = FirebaseAuth.AuthStateListener { trySend(it.currentUser) }
        auth.addAuthStateListener(listener)
        awaitClose { auth.removeAuthStateListener(listener) }
    }

    suspend fun signInWithGoogle(idToken: String): FirebaseUser {
        val credential = GoogleAuthProvider.getCredential(idToken, null)
        val result = auth.signInWithCredential(credential).await()
        return result.user ?: error("Google sign-in failed")
    }

    suspend fun signInWithEmail(email: String, password: String): FirebaseUser {
        val result = auth.signInWithEmailAndPassword(email, password).await()
        return result.user ?: error("Sign-in failed")
    }

    suspend fun registerWithEmail(email: String, password: String): FirebaseUser {
        val result = auth.createUserWithEmailAndPassword(email, password).await()
        return result.user ?: error("Registration failed")
    }

    fun signOut() = auth.signOut()
}

package com.example.spendwiseai.data.repository

import com.example.spendwiseai.domain.model.TransactionType
import com.google.firebase.auth.FirebaseAuth
import com.google.firebase.firestore.FirebaseFirestore
import com.google.firebase.firestore.SetOptions
import kotlinx.coroutines.tasks.await

class FirestoreRepository {
    private val db = FirebaseFirestore.getInstance()
    private val auth = FirebaseAuth.getInstance()
    private val uid get() = auth.currentUser?.uid
    private fun txCollection() = uid?.let {
        db.collection("users").document(it).collection("transactions")
    }

    suspend fun upsertTransaction(id: Long, amount: Double, currency: String,
        categoryName: String, description: String, dateMillis: Long, type: TransactionType) {
        val col = txCollection() ?: return
        val data = mapOf("id" to id, "amount" to amount, "currency" to currency,
            "categoryName" to categoryName, "description" to description,
            "dateMillis" to dateMillis, "type" to type.name)
        col.document(id.toString()).set(data, SetOptions.merge()).await()
    }

    suspend fun deleteTransaction(id: Long) {
        txCollection()?.document(id.toString())?.delete()?.await()
    }

    suspend fun fetchAllTransactions(): List<FirestoreTransaction> {
        val col = txCollection() ?: return emptyList()
        return col.get().await().documents.mapNotNull { doc ->
            try {
                FirestoreTransaction(
                    id = doc.getLong("id") ?: return@mapNotNull null,
                    amount = doc.getDouble("amount") ?: 0.0,
                    currency = doc.getString("currency") ?: "TL",
                    categoryName = doc.getString("categoryName") ?: "Other",
                    description = doc.getString("description") ?: "",
                    dateMillis = doc.getLong("dateMillis") ?: 0L,
                    type = TransactionType.valueOf(doc.getString("type") ?: "EXPENSE")
                )
            } catch (e: Exception) { null }
        }
    }
}

data class FirestoreTransaction(
    val id: Long, val amount: Double, val currency: String,
    val categoryName: String, val description: String,
    val dateMillis: Long, val type: TransactionType
)

package com.example.spendwiseai.data.repository

import com.example.spendwiseai.data.db.TransactionEntity
import com.example.spendwiseai.data.db.dao.TransactionDao
import com.example.spendwiseai.data.db.dao.TransactionWithCategory
import com.example.spendwiseai.domain.model.ParsedTransaction
import com.example.spendwiseai.domain.model.TransactionType
import kotlinx.coroutines.flow.Flow

class TransactionRepository(
    private val transactionDao: TransactionDao,
    private val categoryRepository: CategoryRepository
) {
    suspend fun addTransaction(
        transaction: ParsedTransaction,
        description: String,
        dateMillis: Long
    ): Long {
        val categoryId = categoryRepository.getOrCreateCategoryId(transaction.category)
        return transactionDao.insert(
            TransactionEntity(
                amount = transaction.amount,
                currency = transaction.currency,
                categoryId = categoryId,
                description = description.trim(),
                dateMillis = dateMillis,
                type = transaction.type
            )
        )
    }

    fun observeTransactions(type: TransactionType): Flow<List<TransactionWithCategory>> {
        return transactionDao.observeTransactions(type)
    }

    suspend fun deleteTransaction(id: Long) {
        transactionDao.deleteById(id)
    }

    suspend fun getTransactionById(id: Long): TransactionWithCategory? {
        return transactionDao.getTransactionById(id)
    }

    suspend fun updateTransaction(
        id: Long,
        amount: Double,
        currency: String,
        categoryName: String,
        description: String,
        dateMillis: Long,
        type: TransactionType
    ) {
        val categoryId = categoryRepository.getOrCreateCategoryId(categoryName)
        transactionDao.update(
            TransactionEntity(
                id = id,
                amount = amount,
                currency = currency,
                categoryId = categoryId,
                description = description.trim(),
                dateMillis = dateMillis,
                type = type
            )
        )
    }

    suspend fun getTotalAmountForType(type: TransactionType): Double {
        return transactionDao.getTotalAmountForType(type)
    }

    fun observeTotalAmountForType(type: TransactionType): Flow<Double> {
        return transactionDao.observeTotalAmountForType(type)
    }

    suspend fun getAmountBetween(type: TransactionType, startMillis: Long, endMillis: Long): Double {
        return transactionDao.getAmountBetween(type, startMillis, endMillis)
    }

    fun observeAmountBetween(type: TransactionType, startMillis: Long, endMillis: Long): Flow<Double> {
        return transactionDao.observeAmountBetween(type, startMillis, endMillis)
    }

    suspend fun getCategoryTotalsBetween(
        type: TransactionType,
        startMillis: Long,
        endMillis: Long
    ): List<com.example.spendwiseai.data.db.dao.CategoryTotal> {
        return transactionDao.getCategoryTotalsBetween(type, startMillis, endMillis)
    }

    fun observeCategoryTotalsBetween(
        type: TransactionType,
        startMillis: Long,
        endMillis: Long
    ): Flow<List<com.example.spendwiseai.data.db.dao.CategoryTotal>> {
        return transactionDao.observeCategoryTotalsBetween(type, startMillis, endMillis)
    }
}

package com.example.spendwiseai.data.repository

import com.example.spendwiseai.data.db.TransactionEntity
import com.example.spendwiseai.data.db.dao.TransactionDao
import com.example.spendwiseai.data.db.dao.TransactionWithCategory
import com.example.spendwiseai.domain.model.ParsedTransaction
import com.example.spendwiseai.domain.model.TransactionType
import kotlinx.coroutines.flow.Flow

class TransactionRepository(
    private val transactionDao: TransactionDao,
    private val categoryRepository: CategoryRepository,
    private val firestoreRepository: FirestoreRepository
) {
    suspend fun addTransaction(
        transaction: ParsedTransaction,
        description: String,
        dateMillis: Long
    ): Long {
        val categoryId = categoryRepository.getOrCreateCategoryId(transaction.category)
        val id = transactionDao.insert(
            TransactionEntity(
                amount = transaction.amount,
                currency = transaction.currency,
                categoryId = categoryId,
                description = description.trim(),
                dateMillis = dateMillis,
                type = transaction.type
            )
        )
        runCatching { firestoreRepository.upsertTransaction(id, transaction.amount, transaction.currency, transaction.category, description.trim(), dateMillis, transaction.type) }
        return id
    }

    fun observeTransactions(type: TransactionType): Flow<List<TransactionWithCategory>> {
        return transactionDao.observeTransactions(type)
    }

    suspend fun deleteTransaction(id: Long) {
        transactionDao.deleteById(id)
        runCatching { firestoreRepository.deleteTransaction(id) }
    }

    suspend fun getTransactionById(id: Long): TransactionWithCategory? {
        return transactionDao.getTransactionById(id)
    }

    suspend fun updateTransaction(
        id: Long,
        amount: Double,
        currency: String,
        categoryName: String,
        description: String,
        dateMillis: Long,
        type: TransactionType
    ) {
        val categoryId = categoryRepository.getOrCreateCategoryId(categoryName)
        transactionDao.update(
            TransactionEntity(
                id = id,
                amount = amount,
                currency = currency,
                categoryId = categoryId,
                description = description.trim(),
                dateMillis = dateMillis,
                type = type
            )
        )
        runCatching { firestoreRepository.upsertTransaction(id, amount, currency, categoryName, description.trim(), dateMillis, type) }
    }

    suspend fun getTotalAmountForType(type: TransactionType): Double {
        return transactionDao.getTotalAmountForType(type)
    }

    fun observeTotalAmountForType(type: TransactionType): Flow<Double> {
        return transactionDao.observeTotalAmountForType(type)
    }

    suspend fun getAmountBetween(type: TransactionType, startMillis: Long, endMillis: Long): Double {
        return transactionDao.getAmountBetween(type, startMillis, endMillis)
    }

    fun observeAmountBetween(type: TransactionType, startMillis: Long, endMillis: Long): Flow<Double> {
        return transactionDao.observeAmountBetween(type, startMillis, endMillis)
    }

    suspend fun getCategoryTotalsBetween(
        type: TransactionType,
        startMillis: Long,
        endMillis: Long
    ): List<com.example.spendwiseai.data.db.dao.CategoryTotal> {
        return transactionDao.getCategoryTotalsBetween(type, startMillis, endMillis)
    }

    fun observeCategoryTotalsBetween(
        type: TransactionType,
        startMillis: Long,
        endMillis: Long
    ): Flow<List<com.example.spendwiseai.data.db.dao.CategoryTotal>> {
        return transactionDao.observeCategoryTotalsBetween(type, startMillis, endMillis)
    }

    suspend fun syncFromFirestore() {
        val remote = firestoreRepository.fetchAllTransactions()
        remote.forEach { tx ->
            val categoryId = categoryRepository.getOrCreateCategoryId(tx.categoryName)
            if (transactionDao.getTransactionById(tx.id) == null) {
                transactionDao.insert(TransactionEntity(
                    id = tx.id, amount = tx.amount, currency = tx.currency,
                    categoryId = categoryId, description = tx.description,
                    dateMillis = tx.dateMillis, type = tx.type
                ))
            }
        }
    }
}

package com.example.spendwiseai.presentation.auth

import androidx.lifecycle.ViewModel
import androidx.lifecycle.viewModelScope
import com.example.spendwiseai.data.repository.AuthRepository
import com.example.spendwiseai.data.repository.TransactionRepository
import kotlinx.coroutines.flow.MutableStateFlow
import kotlinx.coroutines.flow.asStateFlow
import kotlinx.coroutines.launch

class LoginViewModel(
    private val authRepository: AuthRepository,
    private val transactionRepository: TransactionRepository
) : ViewModel() {
    private val _uiState = MutableStateFlow(LoginUiState())
    val uiState = _uiState.asStateFlow()

    fun signInWithGoogle(idToken: String) = viewModelScope.launch {
        _uiState.value = LoginUiState(isLoading = true)
        runCatching { authRepository.signInWithGoogle(idToken) }
            .onSuccess { transactionRepository.syncFromFirestore()
                         _uiState.value = LoginUiState(isLoggedIn = true) }
            .onFailure { _uiState.value = LoginUiState(errorMessage = it.message) }
    }

    fun signInWithEmail(email: String, password: String) = viewModelScope.launch {
        if (email.isBlank() || password.isBlank()) {
            _uiState.value = LoginUiState(errorMessage = "E-posta ve şifre boş olamaz"); return@launch
        }
        _uiState.value = LoginUiState(isLoading = true)
        runCatching { authRepository.signInWithEmail(email, password) }
            .onSuccess { transactionRepository.syncFromFirestore()
                         _uiState.value = LoginUiState(isLoggedIn = true) }
            .onFailure { _uiState.value = LoginUiState(errorMessage = it.message) }
    }

    fun registerWithEmail(email: String, password: String) = viewModelScope.launch {
        if (email.isBlank() || password.length < 6) {
            _uiState.value = LoginUiState(errorMessage = "Şifre en az 6 karakter olmalı"); return@launch
        }
        _uiState.value = LoginUiState(isLoading = true)
        runCatching { authRepository.registerWithEmail(email, password) }
            .onSuccess { _uiState.value = LoginUiState(isLoggedIn = true) }
            .onFailure { _uiState.value = LoginUiState(errorMessage = it.message) }
    }

    fun clearError() { _uiState.value = _uiState.value.copy(errorMessage = null) }

    fun setError(message: String) {
        _uiState.value = LoginUiState(errorMessage = message)
    }
}

package com.example.spendwiseai.presentation.auth

import androidx.lifecycle.ViewModel
import androidx.lifecycle.ViewModelProvider
import com.example.spendwiseai.data.repository.AuthRepository
import com.example.spendwiseai.data.repository.TransactionRepository

class LoginViewModelFactory(
    private val authRepository: AuthRepository,
    private val transactionRepository: TransactionRepository
) : ViewModelProvider.Factory {
    @Suppress("UNCHECKED_CAST")
    override fun <T : ViewModel> create(modelClass: Class<T>): T {
        if (modelClass.isAssignableFrom(LoginViewModel::class.java)) {
            return LoginViewModel(authRepository, transactionRepository) as T
        }
        throw IllegalArgumentException("Unknown ViewModel class")
    }
}

