package com.example.spendwiseai.ui.navigation

import androidx.compose.runtime.Composable
import androidx.compose.runtime.remember
import androidx.lifecycle.viewmodel.compose.viewModel
import androidx.navigation.NavHostController
import androidx.navigation.compose.NavHost
import androidx.navigation.compose.composable
import androidx.compose.ui.res.stringResource
import com.example.spendwiseai.core.AppContainer
import com.example.spendwiseai.presentation.SpendWiseViewModelFactory
import com.example.spendwiseai.presentation.expense.AddExpenseViewModel
import com.example.spendwiseai.presentation.budget.BudgetViewModelFactory
import com.example.spendwiseai.presentation.transactions.TransactionsListViewModelFactory
import com.example.spendwiseai.presentation.insights.InsightsViewModelFactory
import com.example.spendwiseai.ui.screens.AddExpenseScreen
import com.example.spendwiseai.ui.screens.BudgetScreen
import com.example.spendwiseai.ui.screens.HomeScreen
import com.example.spendwiseai.ui.screens.InsightsScreen
import com.example.spendwiseai.ui.screens.TransactionsListScreen
import com.example.spendwiseai.presentation.dashboard.DashboardViewModelFactory

@Composable
fun SpendWiseNavHost(
    navController: NavHostController,
    appContainer: AppContainer
) {
    val transactionRepository = appContainer.provideTransactionRepository()

    // transactionRepository kaldırıldı — AddExpenseViewModel artık buna ihtiyaç duymuyor
    val addExpenseViewModelFactory = remember(appContainer) {
        SpendWiseViewModelFactory(
            addExpenseUseCase = appContainer.getAddExpenseUseCase()
        )
    }

    NavHost(
        navController = navController,
        startDestination = SpendWiseRoutes.Home.route
    ) {
        composable(SpendWiseRoutes.Home.route) {
            val dashboardFactory = remember(appContainer) {
                DashboardViewModelFactory(transactionRepository)
            }
            val dashboardVm: com.example.spendwiseai.presentation.dashboard.DashboardViewModel =
                viewModel(factory = dashboardFactory)
            HomeScreen(
                onAddExpenseClicked = { navController.navigate(SpendWiseRoutes.Add.route) },
                dashboardViewModel = dashboardVm
            )
        }

        composable(SpendWiseRoutes.Add.route) {
            val vm: AddExpenseViewModel = viewModel(factory = addExpenseViewModelFactory)
            AddExpenseScreen(
                viewModel = vm,
                onBack = { navController.popBackStack() },
                onSaved = {
                    navController.navigate(SpendWiseRoutes.Home.route) {
                        popUpTo(SpendWiseRoutes.Home.route) { inclusive = false }
                        launchSingleTop = true
                    }
                }
            )
        }

        composable(SpendWiseRoutes.Expenses.route) {
            val factory = remember {
                TransactionsListViewModelFactory(
                    transactionType = com.example.spendwiseai.domain.model.TransactionType.EXPENSE,
                    transactionRepository = transactionRepository
                )
            }
            val vm: com.example.spendwiseai.presentation.transactions.TransactionsListViewModel =
                viewModel(factory = factory)
            TransactionsListScreen(
                transactionType = com.example.spendwiseai.domain.model.TransactionType.EXPENSE,
                viewModel = vm,
                title = stringResource(id = com.example.spendwiseai.R.string.expense)
            )
        }

        composable(SpendWiseRoutes.Incomes.route) {
            val factory = remember {
                TransactionsListViewModelFactory(
                    transactionType = com.example.spendwiseai.domain.model.TransactionType.INCOME,
                    transactionRepository = transactionRepository
                )
            }
            val vm: com.example.spendwiseai.presentation.transactions.TransactionsListViewModel =
                viewModel(factory = factory)
            TransactionsListScreen(
                transactionType = com.example.spendwiseai.domain.model.TransactionType.INCOME,
                viewModel = vm,
                title = stringResource(id = com.example.spendwiseai.R.string.income)
            )
        }

        composable(SpendWiseRoutes.Insights.route) {
            val insightsFactory = remember(appContainer) {
                InsightsViewModelFactory(
                    insightsRepository = appContainer.provideInsightsRepository(),
                    transactionRepository = transactionRepository,
                    generator = appContainer.provideInsightsGenerator()
                )
            }
            val vm: com.example.spendwiseai.presentation.insights.InsightsViewModel =
                viewModel(factory = insightsFactory)
            InsightsScreen(
                viewModel = vm,
                onBackToHome = { navController.navigate(SpendWiseRoutes.Home.route) }
            )
        }

        composable(SpendWiseRoutes.Budget.route) {
            val context = androidx.compose.ui.platform.LocalContext.current
            val factory = remember(appContainer) {
                BudgetViewModelFactory(
                    context = context.applicationContext,
                    transactionRepository = transactionRepository
                )
            }
            val vm: com.example.spendwiseai.presentation.budget.BudgetViewModel =
                viewModel(factory = factory)
            BudgetScreen(viewModel = vm)
        }
    }
}

private object SpendWiseRoutes {
    val Home = Route("home")
    val Add = Route("add")
    val Expenses = Route("expenses")
    val Incomes = Route("incomes")
    val Insights = Route("insights")
    val Budget = Route("budget")

    data class Route(val route: String)
}

package com.example.spendwiseai.ui.navigation

import androidx.compose.runtime.Composable
import androidx.compose.runtime.remember
import androidx.lifecycle.viewmodel.compose.viewModel
import androidx.navigation.NavHostController
import androidx.navigation.compose.NavHost
import androidx.navigation.compose.composable
import androidx.compose.ui.res.stringResource
import com.example.spendwiseai.core.AppContainer
import com.example.spendwiseai.presentation.SpendWiseViewModelFactory
import com.example.spendwiseai.presentation.expense.AddExpenseViewModel
import com.example.spendwiseai.presentation.budget.BudgetViewModelFactory
import com.example.spendwiseai.presentation.transactions.TransactionsListViewModelFactory
import com.example.spendwiseai.presentation.insights.InsightsViewModelFactory
import com.example.spendwiseai.ui.screens.AddExpenseScreen
import com.example.spendwiseai.ui.screens.BudgetScreen
import com.example.spendwiseai.ui.screens.HomeScreen
import com.example.spendwiseai.ui.screens.InsightsScreen
import com.example.spendwiseai.ui.screens.TransactionsListScreen
import com.example.spendwiseai.ui.screens.LoginScreen
import com.example.spendwiseai.presentation.dashboard.DashboardViewModelFactory
import com.google.firebase.auth.FirebaseAuth

@Composable
fun SpendWiseNavHost(
    navController: NavHostController,
    appContainer: AppContainer
) {
    val transactionRepository = appContainer.provideTransactionRepository()

    // transactionRepository kaldırıldı — AddExpenseViewModel artık buna ihtiyaç duymuyor
    val addExpenseViewModelFactory = remember(appContainer) {
        SpendWiseViewModelFactory(
            addExpenseUseCase = appContainer.getAddExpenseUseCase()
        )
    }

    NavHost(
        navController = navController,
        startDestination = if (FirebaseAuth.getInstance().currentUser != null) SpendWiseRoutes.Home.route else SpendWiseRoutes.Login.route
    ) {
        composable(SpendWiseRoutes.Home.route) {
            val dashboardFactory = remember(appContainer) {
                DashboardViewModelFactory(transactionRepository)
            }
            val dashboardVm: com.example.spendwiseai.presentation.dashboard.DashboardViewModel =
                viewModel(factory = dashboardFactory)
            HomeScreen(
                onAddExpenseClicked = { navController.navigate(SpendWiseRoutes.Add.route) },
                dashboardViewModel = dashboardVm
            )
        }

        composable(SpendWiseRoutes.Add.route) {
            val vm: AddExpenseViewModel = viewModel(factory = addExpenseViewModelFactory)
            AddExpenseScreen(
                viewModel = vm,
                onBack = { navController.popBackStack() },
                onSaved = {
                    navController.navigate(SpendWiseRoutes.Home.route) {
                        popUpTo(SpendWiseRoutes.Home.route) { inclusive = false }
                        launchSingleTop = true
                    }
                }
            )
        }

        composable(SpendWiseRoutes.Expenses.route) {
            val factory = remember {
                TransactionsListViewModelFactory(
                    transactionType = com.example.spendwiseai.domain.model.TransactionType.EXPENSE,
                    transactionRepository = transactionRepository
                )
            }
            val vm: com.example.spendwiseai.presentation.transactions.TransactionsListViewModel =
                viewModel(factory = factory)
            TransactionsListScreen(
                transactionType = com.example.spendwiseai.domain.model.TransactionType.EXPENSE,
                viewModel = vm,
                title = stringResource(id = com.example.spendwiseai.R.string.expense)
            )
        }

        composable(SpendWiseRoutes.Incomes.route) {
            val factory = remember {
                TransactionsListViewModelFactory(
                    transactionType = com.example.spendwiseai.domain.model.TransactionType.INCOME,
                    transactionRepository = transactionRepository
                )
            }
            val vm: com.example.spendwiseai.presentation.transactions.TransactionsListViewModel =
                viewModel(factory = factory)
            TransactionsListScreen(
                transactionType = com.example.spendwiseai.domain.model.TransactionType.INCOME,
                viewModel = vm,
                title = stringResource(id = com.example.spendwiseai.R.string.income)
            )
        }

        composable(SpendWiseRoutes.Insights.route) {
            val insightsFactory = remember(appContainer) {
                InsightsViewModelFactory(
                    insightsRepository = appContainer.provideInsightsRepository(),
                    transactionRepository = transactionRepository,
                    generator = appContainer.provideInsightsGenerator()
                )
            }
            val vm: com.example.spendwiseai.presentation.insights.InsightsViewModel =
                viewModel(factory = insightsFactory)
            InsightsScreen(
                viewModel = vm,
                onBackToHome = { navController.navigate(SpendWiseRoutes.Home.route) }
            )
        }

        composable(SpendWiseRoutes.Budget.route) {
            val context = androidx.compose.ui.platform.LocalContext.current
            val factory = remember(appContainer) {
                BudgetViewModelFactory(
                    context = context.applicationContext,
                    transactionRepository = transactionRepository
                )
            }
            val vm: com.example.spendwiseai.presentation.budget.BudgetViewModel =
                viewModel(factory = factory)
            BudgetScreen(viewModel = vm)
        }

        composable(SpendWiseRoutes.Login.route) {
            val vm: com.example.spendwiseai.presentation.auth.LoginViewModel = viewModel(factory = appContainer.provideLoginViewModelFactory())
            LoginScreen(viewModel = vm, onLoginSuccess = {
                navController.navigate(SpendWiseRoutes.Home.route) {
                    popUpTo(SpendWiseRoutes.Login.route) { inclusive = true }
                }
            })
        }
    }
}

private object SpendWiseRoutes {
    val Home = Route("home")
    val Add = Route("add")
    val Expenses = Route("expenses")
    val Incomes = Route("incomes")
    val Insights = Route("insights")
    val Budget = Route("budget")
    val Login = Route("login")

    data class Route(val route: String)
}

package com.example.spendwiseai.ui.screens

import android.app.Activity
import androidx.activity.compose.rememberLauncherForActivityResult
import androidx.activity.result.contract.ActivityResultContracts
import androidx.compose.animation.AnimatedVisibility
import androidx.compose.foundation.background
import androidx.compose.foundation.border
import androidx.compose.foundation.clickable
import androidx.compose.foundation.layout.*
import androidx.compose.foundation.shape.RoundedCornerShape
import androidx.compose.foundation.text.KeyboardOptions
import androidx.compose.material.icons.Icons
import androidx.compose.material.icons.filled.Visibility
import androidx.compose.material.icons.filled.VisibilityOff
import androidx.compose.material3.*
import androidx.compose.runtime.*
import androidx.compose.ui.Alignment
import androidx.compose.ui.Modifier
import androidx.compose.ui.draw.clip
import androidx.compose.ui.graphics.Brush
import androidx.compose.ui.graphics.Color
import androidx.compose.ui.platform.LocalContext
import androidx.compose.ui.res.stringResource
import androidx.compose.ui.text.font.FontWeight
import androidx.compose.ui.text.input.KeyboardType
import androidx.compose.ui.text.input.PasswordVisualTransformation
import androidx.compose.ui.text.input.VisualTransformation
import androidx.compose.ui.unit.dp
import androidx.compose.ui.unit.sp
import com.example.spendwiseai.R
import com.example.spendwiseai.presentation.auth.LoginViewModel
import com.google.android.gms.auth.api.signin.GoogleSignIn
import com.google.android.gms.auth.api.signin.GoogleSignInOptions
import com.google.android.gms.common.api.ApiException
import kotlinx.coroutines.launch

private val AppBackground = Color(0xFF07090C)
private val NeonGreen = Color(0xFF27E56B)
private val SoftCoralRed = Color(0xFFFF6B6B)
private val GlassSurface = Color(0x1AFFFFFF)

@Composable
fun LoginScreen(
    viewModel: LoginViewModel,
    onLoginSuccess: () -> Unit
) {
    val context = LocalContext.current
    val scope = rememberCoroutineScope()
    val uiState by viewModel.uiState.collectAsState()
    var isRegisterMode by remember { mutableStateOf(false) }
    var email by remember { mutableStateOf("") }
    var password by remember { mutableStateOf("") }
    var passwordVisible by remember { mutableStateOf(false) }

    val googleSignInLauncher = rememberLauncherForActivityResult(
        contract = ActivityResultContracts.StartActivityForResult()
    ) { result ->
        if (result.resultCode == Activity.RESULT_OK) {
            try {
                val task = GoogleSignIn.getSignedInAccountFromIntent(result.data)
                val account = task.getResult(ApiException::class.java)
                val idToken = account?.idToken
                if (idToken != null) {
                    viewModel.signInWithGoogle(idToken)
                } else {
                    viewModel.setError("Google token alınamadı. Firebase Console'da SHA-1 ekli mi?")
                }
            } catch (e: ApiException) {
                viewModel.setError("Google giriş hatası: ${e.statusCode}")
            }
        }
    }

    val webClientId = stringResource(com.example.spendwiseai.R.string.default_web_client_id)

    val gso = GoogleSignInOptions.Builder(GoogleSignInOptions.DEFAULT_SIGN_IN)
        .requestIdToken(stringResource(R.string.default_web_client_id))
        .requestEmail()
        .build()
    val googleClient = remember(context) { GoogleSignIn.getClient(context, gso) }

    LaunchedEffect(uiState.isLoggedIn) {
        if (uiState.isLoggedIn) {
            onLoginSuccess()
        }
    }

    Box(
        modifier = Modifier
            .fillMaxSize()
            .background(
                Brush.verticalGradient(
                    colors = listOf(Color(0xFF070A0F), AppBackground)
                )
            )
    ) {
        Column(
            modifier = Modifier
                .fillMaxSize()
                .padding(24.dp),
            horizontalAlignment = Alignment.CenterHorizontally,
            verticalArrangement = Arrangement.Center
        ) {
            Text(
                text = "",
                fontSize = 56.sp
            )
            Text(
                text = "SpendWise AI",
                fontSize = 28.sp,
                fontWeight = FontWeight.Bold,
                color = Color.White
            )
            Spacer(modifier = Modifier.height(8.dp))
            Text(
                text = if (isRegisterMode) "Hesap oluştur" else "Hesabına giriş yap",
                fontSize = 18.sp,
                color = Color.White.copy(alpha = 0.7f)
            )
            Spacer(modifier = Modifier.height(32.dp))

            // Google Sign-In Button
            Box(
                modifier = Modifier
                    .fillMaxWidth()
                    .clip(RoundedCornerShape(14.dp))
                    .background(Color.Black.copy(alpha = 0.5f))
                    .border(1.dp, Color.White.copy(alpha = 0.3f), RoundedCornerShape(14.dp))
                    .clickable {
                        googleClient.signOut().addOnCompleteListener {
                            googleSignInLauncher.launch(googleClient.signInIntent)
                        }
                    }
                    .padding(vertical = 14.dp),
                contentAlignment = Alignment.Center
            ) {
                Row(
                    verticalAlignment = Alignment.CenterVertically
                ) {
                    Text(
                        text = "G",
                        color = NeonGreen,
                        fontSize = 20.sp,
                        fontWeight = FontWeight.Bold
                    )
                    Spacer(modifier = Modifier.width(8.dp))
                    Text(
                        text = "Google ile devam et",
                        color = Color.White,
                        fontSize = 16.sp
                    )
                }
            }

            Spacer(modifier = Modifier.height(16.dp))

            // Divider
            Row(
                modifier = Modifier.fillMaxWidth(),
                verticalAlignment = Alignment.CenterVertically
            ) {
                Box(
                    modifier = Modifier
                        .weight(1f)
                        .height(1.dp)
                        .background(Color.White.copy(alpha = 0.3f))
                )
                Text(
                    text = "ya da",
                    color = Color.White.copy(alpha = 0.3f),
                    modifier = Modifier.padding(horizontal = 16.dp)
                )
                Box(
                    modifier = Modifier
                        .weight(1f)
                        .height(1.dp)
                        .background(Color.White.copy(alpha = 0.3f))
                )
            }

            Spacer(modifier = Modifier.height(16.dp))

            // Email Field
            OutlinedTextField(
                value = email,
                onValueChange = { email = it },
                label = { Text("E-posta", color = Color.White.copy(alpha = 0.7f)) },
                modifier = Modifier.fillMaxWidth(),
                colors = OutlinedTextFieldDefaults.colors(
                    focusedContainerColor = Color.Black.copy(alpha = 0.5f),
                    unfocusedContainerColor = Color.Black.copy(alpha = 0.5f),
                    focusedBorderColor = NeonGreen,
                    unfocusedBorderColor = Color.White.copy(alpha = 0.3f),
                    cursorColor = NeonGreen,
                    focusedTextColor = Color.White,
                    unfocusedTextColor = Color.White
                ),
                keyboardOptions = KeyboardOptions(keyboardType = KeyboardType.Email)
            )

            Spacer(modifier = Modifier.height(16.dp))

            // Password Field
            OutlinedTextField(
                value = password,
                onValueChange = { password = it },
                label = { Text("Şifre", color = Color.White.copy(alpha = 0.7f)) },
                modifier = Modifier.fillMaxWidth(),
                visualTransformation = if (passwordVisible) VisualTransformation.None else PasswordVisualTransformation(),
                trailingIcon = {
                    IconButton(onClick = { passwordVisible = !passwordVisible }) {
                        Icon(
                            imageVector = if (passwordVisible) Icons.Filled.Visibility else Icons.Filled.VisibilityOff,
                            contentDescription = "Toggle password visibility",
                            tint = Color.White.copy(alpha = 0.7f)
                        )
                    }
                },
                colors = OutlinedTextFieldDefaults.colors(
                    focusedContainerColor = Color.Black.copy(alpha = 0.5f),
                    unfocusedContainerColor = Color.Black.copy(alpha = 0.5f),
                    focusedBorderColor = NeonGreen,
                    unfocusedBorderColor = Color.White.copy(alpha = 0.3f),
                    cursorColor = NeonGreen,
                    focusedTextColor = Color.White,
                    unfocusedTextColor = Color.White
                ),
                keyboardOptions = KeyboardOptions(keyboardType = KeyboardType.Password)
            )

            Spacer(modifier = Modifier.height(24.dp))

            // Error Message
            AnimatedVisibility(visible = uiState.errorMessage != null) {
                Text(
                    text = uiState.errorMessage ?: "",
                    color = SoftCoralRed,
                    modifier = Modifier.fillMaxWidth(),
                    textAlign = androidx.compose.ui.text.style.TextAlign.Center
                )
            }

            Spacer(modifier = Modifier.height(16.dp))

            // Login/Register Button
            Button(
                onClick = {
                    if (isRegisterMode) {
                        viewModel.registerWithEmail(email, password)
                    } else {
                        viewModel.signInWithEmail(email, password)
                    }
                },
                modifier = Modifier
                    .fillMaxWidth()
                    .height(52.dp),
                colors = ButtonDefaults.buttonColors(containerColor = NeonGreen),
                shape = RoundedCornerShape(14.dp),
                enabled = !uiState.isLoading
            ) {
                if (uiState.isLoading) {
                    CircularProgressIndicator(color = Color.Black)
                } else {
                    Text(
                        text = if (isRegisterMode) "Kayıt Ol" else "Giriş Yap",
                        color = Color.Black,
                        fontWeight = FontWeight.SemiBold,
                        fontSize = 16.sp
                    )
                }
            }

            Spacer(modifier = Modifier.height(16.dp))

            // Toggle Mode
            Row(
                modifier = Modifier.fillMaxWidth(),
                horizontalArrangement = Arrangement.Center
            ) {
                Text(
                    text = if (isRegisterMode) "Hesabın var mı? " else "Hesabın yok mu? ",
                    color = Color.White.copy(alpha = 0.7f)
                )
                Text(
                    text = if (isRegisterMode) "Giriş yap" else "Kayıt ol",
                    color = NeonGreen,
                    fontWeight = FontWeight.SemiBold,
                    modifier = Modifier.clickable {
                        isRegisterMode = !isRegisterMode
                        viewModel.clearError()
                    }
                )
            }
        }
    }
}

